const items = $input.all().map(i => i.json).filter(ap => ap && ap.id && ap.estado === 'activo' && ap.fecha_limite);
const hoy = new Intl.DateTimeFormat('en-CA', { timeZone: 'Europe/Madrid' }).format(new Date());
const msHoy = Date.parse(`${hoy}T00:00:00Z`);

const staticData = $getWorkflowStaticData('global');
if (!staticData.enviados) {
  staticData.enviados = {};
}

let asuntosMailpit = [];
try {
  const resp = await this.helpers.httpRequest({
    method: 'GET',
    url: 'http://mailpit:8025/api/v1/messages?limit=200',
    json: true
  });
  asuntosMailpit = (resp?.messages || []).map(m => String(m.Subject || ''));
} catch (_e) {
  asuntosMailpit = [];
}

const seleccionados = [];
for (const ap of items) {
  const msLimite = Date.parse(`${ap.fecha_limite}T00:00:00Z`);
  const diasRestantes = Math.round((msLimite - msHoy) / 86400000);
  if (diasRestantes !== 7 && diasRestantes !== 1) {
    continue;
  }

  const claveAviso = `apartado-${ap.id}-aviso-${diasRestantes}d-${ap.fecha_limite}`;
  const marcaId = `apartado nº ${ap.id}`;
  const marcaPlazo = diasRestantes === 7 ? '7 días' : 'Mañana vence';
  const marcaSinEmail = `Recordatorio sin email (${diasRestantes}d) · apartado nº ${ap.id}`;

  const yaEnBuzon = asuntosMailpit.some(asunto =>
    (asunto.includes(marcaId) && asunto.includes(marcaPlazo)) || asunto.includes(marcaSinEmail)
  );
  const yaEnStatic = Boolean(staticData.enviados[claveAviso]) && (asuntosMailpit.length === 0 || yaEnBuzon);

  if (yaEnBuzon || yaEnStatic) {
    continue;
  }

  staticData.enviados[claveAviso] = hoy;
  const fechaLimiteEs = String(ap.fecha_limite).split('-').reverse().join('/');
  seleccionados.push({
    json: {
      ...ap,
      dias_restantes: diasRestantes,
      fecha_limite_es: fechaLimiteEs,
      clave_aviso: claveAviso
    }
  });
}

return seleccionados;
